import {PROJECT_STATUSES} from './projects.js';
import {migratePersonalization,normalizeSiteUrl} from './profile.js';
import {renderPublicSite,publicSnapshot} from './public-site.js';
import './style.css';
import {GRADES,uid,initial,validate,gpa,point,isFail,attendance,assessmentStats,requiredGpa,markGrade,assessmentTemplate} from './core.js';
// Retain the legacy storage key so the rename does not lose existing records.
const KEY='verdant.personal.v1';let data,storageOK=true;
try{data=localStorage.getItem(KEY)?validate(JSON.parse(localStorage.getItem(KEY))):initial();}catch(e){data=initial();storageOK=false;}
data=migratePersonalization(data);
if(storageOK){try{localStorage.setItem(KEY,JSON.stringify(data));}catch{storageOK=false;}}
let activeNote='',noteSearch='',projectFilter='All';
let page=location.hash.slice(1)||'overview',semester=1,scenario=false,selected=data.courses[0]?.id,search='';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={leaf:'M20 4C10 2 3 6 5 14c3 7 14 4 15-10ZM5 20l10-10',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',book:'M3 4h7l2 2 2-2h7v15h-7l-2 2-2-2H3zM12 6v15',chart:'M4 3v17h17M8 15v-4M13 15V7M18 15V4',check:'M4 12l5 5L20 6',calendar:'M4 5h16v16H4zM8 3v4M16 3v4M4 10h16',target:'M20 12a8 8 0 1 1-8-8M12 12l9-9M16 3h5v5M15 12a3 3 0 1 1-3-3',bulb:'M9 18h6M10 21h4M8 15a6 6 0 1 1 8 0l-1 3H9z',person:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM4 21v-2a8 8 0 0 1 16 0v2',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',arrow:'M4 12h16M14 6l6 6-6 6',plus:'M12 5v14M5 12h14',download:'M12 3v12M7 10l5 5 5-5M4 16v5h16v-5',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',menu:'M3 6h18M3 12h18M3 18h18',close:'M6 6l12 12M6 18 18 6',edit:'m4 16 12-12 4 4L8 20H4z',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3z',folder:'M3 5h7l2 3h9v12H3z',external:'M14 3h7v7M21 3 11 13M10 3H3v18h18v-7'};
const icon=(n,size=20)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.grid}"/></svg>`;
const button=(label,action,cls='',attrs='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const fmt=n=>n===null||n===undefined?'—':Number(n).toFixed(2);
const percent=n=>n===null?'—':`${Number(n).toFixed(1)}%`;
const semCourses=()=>data.courses.filter(c=>c.semester===semester);
const sourceLinks=`<a href="https://webfiles.amrita.edu/2024/07/btech-school-computing-regulations-2023.pdf" target="_blank" rel="noopener">[2] School of Computing regulations · May 2024 ↗</a><a href="https://webfiles.amrita.edu/2023/07/btech-artificial-intelligence-datascience-curriculum-syllabus-2023.pdf" target="_blank" rel="noopener">[1] AI & DS curriculum · 2023 ↗</a>`;
const pages=[['overview','Overview','grid'],['courses','My courses','book'],['grades','SGPA & CGPA','chart'],['attendance','Attendance','check'],['assessments','Assessments','calendar'],['planner','Goal planner','target'],['timetable','Timetable','clock'],['notes','Notes','book'],['projects','Project dashboard','folder'],['ideas','Idea garden','bulb'],['portfolio','Portfolio & résumé','person'],['settings','Settings & sources','settings']];
function save(){try{localStorage.setItem(KEY,JSON.stringify(data));storageOK=true;}catch{storageOK=false;toast('Browser storage unavailable. Export a backup before leaving.');} }
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function go(p){page=p;location.hash=p;render();window.scrollTo({top:0});}
window.addEventListener('hashchange',()=>{page=location.hash.slice(1)||'overview';render();window.scrollTo({top:0});});
function render(){
 if(!pages.some(x=>x[0]===page))page='overview';document.documentElement.style.setProperty('--accent',data.settings.accent);
 const p=pages.find(x=>x[0]===page);const now=new Date();document.title=p[1]+' · '+data.site.title+(data.site.title.includes('ArchiSpace')?'':' · ArchiSpace');
 $('#app').innerHTML=`<aside class="sidebar"><a class="brand" href="#overview"><span class="brand-icon">${icon('leaf',25)}</span>ArchiSpace<span class="brand-dot">.</span></a><div class="workspace-label">YOUR PERSONAL WORKSPACE</div><nav>${pages.map(([id,label,i],idx)=>`${idx===7?'<div class="nav-caption">BEYOND THE CLASSROOM</div>':''}<a href="#${id}" class="nav-item ${page===id?'active':''}">${icon(i)}<span>${label}</span>${page===id?'<i></i>':''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="grow-note">${icon('spark')}<p>A little better,<br><b>every single day.</b></p></div><div class="user"><span class="avatar">${esc(data.profile.name?data.profile.name.slice(0,2).toUpperCase():'ME')}</span><div><b>${esc(data.profile.name||'Your workspace')}</b><small>AI & DS · Class of 2030*</small></div></div><small class="storage"><i class="${storageOK?'':'warn'}"></i>${storageOK?'Saved in this browser':'Storage unavailable'} · not cloud synced</small></div></aside><div class="main-wrap"><header class="topbar"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Toggle menu">${icon('menu')}</button><div class="crumb">My workspace <span>/</span> <b>${p[1]}</b></div><div class="top-meta"><span class="campus"><i></i> Amrita Bengaluru</span><span class="divider"></span><select id="semester" aria-label="Current semester">${Array.from({length:Math.max(8,...data.courses.map(c=>c.semester))},(_,i)=>`<option value="${i+1}" ${semester===i+1?'selected':''}>Semester ${i+1}</option>`).join('')}</select><span class="top-avatar">${esc(data.profile.name?data.profile.name[0]:'Y')}</span></div></header><main><div class="page-eyebrow">${page==='overview'?now.toLocaleDateString('en-IN',{weekday:'long',day:'numeric',month:'long',year:'numeric'}):'AMRITA · AI & DATA SCIENCE · 2026 ADMISSION'}</div>${({overview,courses,grades,attendance:attendancePage,assessments,planner,timetable,notes:notesPage,projects:projectDashboard,ideas,portfolio,settings}[page])()}<footer>Made for your next chapter. <span>Private workspace · Browser-local data · ${new Date().getFullYear()}</span></footer></main></div>`;
 bindInputs();
}
function heading(title,subtitle,actions=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div><div class="heading-actions">${actions}</div></div>`;}
function tag(t,cls=''){return `<span class="tag ${cls}">${t}</span>`;}
function empty(title,sub,action=''){return `<div class="empty">${icon('leaf',32)}<h3>${title}</h3><p>${sub}</p>${action}</div>`;}
function overview(){
 const cs=semCourses(),g=gpa(cs,data.settings.gradePoints),cum=gpa(data.courses,data.settings.gradePoints),passed=data.courses.filter(c=>c.grade&&(c.pf?c.grade==='PASS':point(c,c.grade,data.settings.gradePoints)>0)).reduce((s,c)=>s+c.credits,0);
 const logged=cs.filter(c=>c.held>0),risk=logged.filter(c=>attendance(c.attended,c.held,data.settings.minimum).pct<data.settings.minimum),tasks=data.tasks.filter(t=>!t.done).sort((a,b)=>(a.date||'9999').localeCompare(b.date||'9999'));
 return heading(`Room to grow${data.profile.name?`, ${esc(data.profile.name.split(' ')[0])}`:''}.`,'Your studies, your ideas, your future. All in one place.',button(`${icon('plus',16)} Capture an idea`,'add-idea',''))+`
 <div class="workspace-shortcuts">${button(`${icon('chart',18)} SGPA & CGPA calculator`,'goto-grades','primary')}${button(`${icon('book',18)} My notes`,'goto-notes')}${button(`${icon('folder',18)} Project dashboard`,'goto-projects')}${button(`${icon('person',18)} Portfolio`,'goto-portfolio')}</div>
 <div class="overview-grid"><section class="hero"><div class="hero-copy"><span class="eyebrow">SMALL STEPS. OUTSTANDING POSSIBILITIES.</span><h2>Build a semester<br>you’re proud of.</h2><p>Aim for excellence. Make a plan.<br>Let consistent effort do the rest.</p>${button(`Plan my next step ${icon('arrow',16)}`,'goto-planner','light')}</div><div class="hero-art"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><svg viewBox="0 0 240 240" aria-hidden="true"><path d="M117 214C90 155 124 100 150 52" fill="none" stroke="#bdd7a5" stroke-width="2"/><path d="M124 149C63 148 52 100 63 77c48-3 80 22 61 72Z" fill="#7caa83"/><path d="M126 116c-7-56 36-83 72-72 7 44-29 79-72 72Z" fill="#bdd7a5"/><path d="M113 185c-45 5-65-18-66-46 31-18 75-1 66 46Z" fill="#437a59"/><path d="M119 165c9-42 44-50 70-35-6 37-35 53-70 35Z" fill="#8cb591"/><path d="m66 79 58 70m4-34 67-68m-76 116 66-30" stroke="#1b4332" opacity=".35" fill="none"/></svg><span>GROW AT YOUR OWN PACE</span></div></section>
 <section class="target-card"><div class="card-top"><span class="eyebrow">THE BIG PICTURE</span>${icon('target')}</div><div class="target-number">${fmt(data.settings.target)}<span>/ 10</span></div><h3>Your CGPA north star</h3><p>Ambitious by design.<br>Achievable with a plan.</p><div class="tiny-line"><span>Current recorded CGPA</span><b>${fmt(cum.value)}</b></div>${button(`Explore your goal ${icon('arrow',15)}`,'goto-planner','text-btn')}</section></div>
 <div class="stats-grid"><div class="stat-card"><span>${icon('chart',18)} SEMESTER GPA</span><strong>${fmt(g.value)}<small>/ 10</small></strong><p>${g.count?`${g.complete?'All GPA credits entered':'Partial · entered grades only'} · ${g.credits} credits`:'Add your grades to get started'}</p></div><div class="stat-card"><span>${icon('book',18)} SEMESTER CREDITS</span><strong>${cs.reduce((s,c)=>s+c.credits,0)}<small>in ${cs.length} courses</small></strong><p>${cs.filter(c=>c.include).reduce((s,c)=>s+c.credits,0)} GPA credits · inclusion is configurable</p></div><div class="stat-card"><span>${icon('check',18)} ATTENDANCE HEALTH</span><strong>${logged.length?risk.length:'—'}<small>${logged.length?'courses below minimum':'not logged yet'}</small></strong><p>${data.settings.minimum}% minimum · ${logged.length} / ${cs.length} courses logged</p></div><div class="stat-card"><span>${icon('leaf',18)} DEGREE JOURNEY</span><strong>${passed}<small>/ ${data.settings.degreeCredits} credits</small></strong><p>Recorded passed credits · target unverified</p></div></div>
 <div class="two-col"><section class="panel"><div class="section-heading"><div><h2>This semester</h2><p>A strong foundation starts here.</p></div>${button('All courses ↗','goto-courses','text-btn')}</div><div class="course-list">${cs.length?cs.slice(0,5).map(c=>`<button class="course-row" data-action="open-course" data-id="${c.id}"><span class="course-letter">${esc(c.slot||c.code.slice(0,1))}</span><span class="course-title"><b>${esc(c.name)}</b><small>${esc(c.code)} <span>·</span> ${c.pf?'Pass / fail':'Letter graded'}</small></span><span class="credit-pill">${c.credits} cr</span>${icon('arrow',17)}</button>`).join(''):empty('A fresh semester','Add courses when your next curriculum arrives.',button('Add course','add-course'))}</div>${cs.length>5?`<div class="panel-bottom">+ ${cs.length-5} more courses in your learning journey</div>`:''}</section>
 <section class="panel focus"><div class="section-heading"><div><h2>Your next small wins</h2><p>Give your attention a direction.</p></div><button class="icon-btn" data-action="add-task" aria-label="Add a task">${icon('plus')}</button></div>${tasks.length?tasks.slice(0,4).map(taskRow).join(''):`<div class="focus-prompt"><span class="soft-icon">${icon('check',24)}</span><h3>Start with one small win.</h3><p>A quiz to prepare for. A project to begin.<br>What will move you forward today?</p>${button('Add your first task','add-task')}</div>`}<div class="focus-tip">${icon('bulb',19)}<p><b>Make space for good ideas.</b><br>Your idea garden is ready whenever inspiration strikes.</p></div></section></div>
 <div class="notice">${icon('settings',18)}<p><b>Your rules, made transparent.</b> Grading uses an Amrita reference preset, not yet confirmed for your batch. FIH is pass/fail and excluded from GPA by default. <button data-action="goto-settings">Review assumptions →</button></p></div>`;
}
function taskRow(t){return `<div class="task-row"><button class="task-check ${t.done?'done':''}" data-action="toggle-task" data-id="${t.id}" aria-label="${t.done?'Reopen':'Complete'} task">${t.done?icon('check',13):''}</button><div><b class="${t.done?'struck':''}">${esc(t.title)}</b><small>${esc(t.date||'No due date')} ${t.course?'· '+esc(data.courses.find(c=>c.id===t.course)?.code||''):''}</small></div><button class="icon-btn" data-action="delete-task" data-id="${t.id}" aria-label="Delete task">${icon('close',14)}</button></div>`;}
function courses(){const cs=semCourses().filter(c=>(c.name+' '+c.code).toLowerCase().includes(search.toLowerCase()));return heading('Your learning, mapped.','Real courses. Real credits. A foundation you can make your own.',button(`${icon('plus',17)} Add course`,'add-course','primary'))+`<div class="toolbar"><div class="chips">${tag(`Semester ${semester}`)}${tag(`${semCourses().length} courses`,'neutral')}${tag(`${semCourses().reduce((s,c)=>s+c.credits,0)} credits`,'neutral')}</div><input id="course-search" placeholder="Find a course…" aria-label="Find a course" value="${esc(search)}"></div><div class="course-grid">${cs.map(c=>`<article class="panel course-card"><div class="card-top"><span class="course-letter">${esc(c.slot||'•')}</span><span class="mono">${esc(c.code)}</span>${button(icon('edit',16),'edit-course','icon-btn',`data-id="${c.id}" aria-label="Edit ${esc(c.name)}"`)}</div><h2>${esc(c.name)}</h2><p>${esc(c.faculty||'Faculty not added')}</p><div class="chips">${tag(`${c.credits} credits`,'neutral')}${tag(c.pf?'Pass / fail':'Letter graded')}${!c.include?tag('Not in GPA','neutral'):''}</div><div class="course-card-bottom"><span>L–T–P <b>${esc(c.ltp||'—')}</b></span>${button('Open course ↗','open-course','text-btn',`data-id="${c.id}"`)}</div></article>`).join('')}</div>${!cs.length?empty('Nothing here yet','Add a course or try a different search.'):''}<p class="fine-print">Semester 1 was transcribed from your 2026–27 timetable. CR is used as credits; lab hours are not added again. Technical Communication uses your timetable’s code, 23ENG101.</p>`;}
function gradeOptions(c,v){return `<option value="">Not entered</option>${(c.pf?['PASS','FAIL']:Object.keys(data.settings.gradePoints).concat('W')).map(g=>`<option value="${g}" ${v===g?'selected':''}>${g}${c.pf?'':` · ${g==='W'?'withheld':data.settings.gradePoints[g]}`}</option>`).join('')}`;}
function grades(){const cs=semCourses(),s=gpa(cs,data.settings.gradePoints,scenario),all=gpa(data.courses,data.settings.gradePoints,scenario);return heading('Every credit counts.','SGPA and CGPA, weighted correctly. Blank grades are never treated as zero.',button('Export grades CSV','export-csv',''))+`<div class="toolbar"><div class="segmented"><button class="${!scenario?'selected':''}" data-action="actual-mode">Recorded grades</button><button class="${scenario?'selected':''}" data-action="scenario-mode">What-if mode</button></div><span class="subtle">${scenario?'Plans never overwrite your recorded grades.':'Use confirmed course grades from your grade sheet.'}</span></div><div class="stats-grid three"><div class="stat-card"><span>SEMESTER ${semester} ${scenario?'PROJECTED':'RECORDED'} GPA</span><strong>${fmt(s.value)}<small>/ 10</small></strong><p>${s.credits} / ${s.possible} GPA credits entered · ${s.complete?'complete coverage':'partial result'}</p></div><div class="stat-card"><span>${scenario?'PROJECTED':'RECORDED'} CGPA</span><strong>${fmt(all.value)}<small>/ 10</small></strong><p>${all.credits} / ${all.possible} GPA credits entered across semesters</p></div><div class="stat-card"><span>CREDIT-WEIGHTED QUALITY POINTS</span><strong>${s.quality.toFixed(1)}</strong><p>Σ (course credits × grade points)</p></div></div><section class="panel table-panel"><div class="table-scroll"><table><thead><tr><th>COURSE</th><th>CREDITS</th><th>IN GPA</th><th>${scenario?'PLANNED GRADE':'RECORDED GRADE'}</th><th>QUALITY POINTS</th><th></th></tr></thead><tbody>${cs.map(c=>{const v=scenario?(c.plan||c.grade):c.grade;const p=point(c,v,data.settings.gradePoints);return `<tr><td><b>${esc(c.name)}</b><small>${esc(c.code)}${c.pf?' · Pass / fail':''}</small></td><td>${c.credits}</td><td>${tag(c.include?'Yes':'Excluded',c.include?'':'neutral')}</td><td><select class="grade-input" data-id="${c.id}" aria-label="${esc(c.name)} grade">${gradeOptions(c,scenario?c.plan:c.grade)}</select>${scenario&&!c.plan&&c.grade?`<small>Falls back to recorded ${esc(c.grade)}</small>`:''}</td><td>${c.include&&p!==null?(c.credits*p).toFixed(1):'—'}</td><td>${button(icon('edit',16),'edit-course','icon-btn',`data-id="${c.id}" aria-label="Edit course"`)}</td></tr>`}).join('')}</tbody></table></div>${!cs.length?empty('No courses in this semester','Add courses from My courses.'):''}</section><div class="two-col equal"><section class="panel padded"><h2>How the calculation works</h2><div class="formula">GPA = Σ (credits × grade points) / Σ credits</div><p>Failed grades count in the GPA denominator with zero points. Blank and withheld grades are unresolved and excluded from the partial preview. No semester GPA is averaged without credit weighting.</p><p>FIH is pass/fail per your information. Its GPA exclusion is an editable assumption, not a verified batch rule.</p></section><section class="panel padded"><h2>Semester breakdown</h2>${[...new Set(data.courses.map(c=>c.semester))].sort((a,b)=>a-b).map(n=>{const a=gpa(data.courses.filter(c=>c.semester===n),data.settings.gradePoints,scenario);return `<div class="breakdown"><span>Semester ${n}</span><span>${a.credits} GPA credits</span><b>${fmt(a.value)}</b></div>`}).join('')}<p class="fine-print">Displayed GPA rounds to 2 decimals; calculations keep full precision.</p></section></div><section class="panel padded"><div class="section-heading"><div><h2>Backlogs & grade history</h2><p>Resolve a course in place only when your official grade is revised. No automatic repeat-course policy is assumed.</p></div></div>${data.courses.filter(c=>isFail(c.grade)||c.history.length).map(c=>`<div class="breakdown"><div><b>${esc(c.name)}</b><small>Current: ${esc(c.grade||'pending')} · ${c.history.length} previous grade changes</small></div>${button('View / update','open-course','',`data-id="${c.id}"`)}</div>`).join('')||'<p class="subtle">No recorded backlogs or grade changes.</p>'}</section>`;}
function attendancePage(){return heading('Show up for your future.','Track each course independently. Attendance counts are not inferred from the timetable.',button('Review minimum','goto-settings'))+`<div class="notice">${icon('bulb')}<p>The minimum is <b>${data.settings.minimum}% per course</b>. Use the same counting unit as your portal (hours or sessions). Never combine lab hours with lecture sessions. This is a planning estimate, not an official attendance record.</p></div><div class="attendance-grid">${semCourses().map(c=>{const a=attendance(c.attended,c.held,data.settings.minimum),low=a.pct!==null&&a.pct<data.settings.minimum;return `<section class="panel attendance-card"><div class="card-top"><span class="mono">${esc(c.code)}</span>${tag(a.pct===null?'Not started':low?'Needs attention':'On track',low?'danger':a.pct===null?'neutral':'')}</div><h3>${esc(c.name)}</h3><div class="att-main"><strong>${percent(a.pct)}</strong><span>${c.attended} / ${c.held} attended</span></div><div class="progress"><i style="width:${a.pct||0}%;background:${low?'#b31237':'var(--accent)'}"></i><em style="left:${data.settings.minimum}%"></em></div><p class="att-advice">${!c.held?'Log your first class to see your buffer.':low?`Attend ${a.need===Infinity?'every future class (100% is unreachable without correcting absences)':`the next <b>${a.need}</b> consecutive classes to reach the minimum`}.`:`You can miss <b>${a.miss}</b> more ${a.miss===1?'class':'classes'} and stay at or above ${data.settings.minimum}%.`}</p><div class="att-actions">${button(`${icon('plus',15)} Attended`,'att-present','',`data-id="${c.id}"`)}${button('Missed','att-missed','',`data-id="${c.id}"`)}${button(icon('edit',15),'edit-attendance','icon-btn',`data-id="${c.id}" aria-label="Edit attendance counts"`)}</div></section>`}).join('')}</div>${!semCourses().length?empty('No courses yet','Add courses to start tracking attendance.'):''}`;}
function assessments(){let c=data.courses.find(c=>c.id===selected&&c.semester===semester)||semCourses()[0];if(!c)return heading('Make every assessment count.','Your marks, weights and next steps.')+empty('No courses yet','Add a course to get started.');selected=c.id;const s=assessmentStats(c.assessments,c.targetMarks),estimated=s.complete&&s.valid?markGrade(s.secured,c.thresholds):null;return heading('Make every assessment count.','Quizzes, exams, labs and participation. Your course, your assessment structure.')+`<div class="toolbar"><select id="assessment-course" aria-label="Assessment course">${semCourses().map(x=>`<option value="${x.id}" ${x.id===c.id?'selected':''}>${esc(x.code)} · ${esc(x.name)}</option>`).join('')}</select>${button('Course rules','open-course','',`data-id="${c.id}"`)}</div><div class="notice">${icon('settings')}<p>${['22ADM101','22AVP103'].includes(c.code)?'Practical / participation-based course. Add the actual project and participation components; no exam split has been assumed.':'The initial 10 / 10 / 50 / 30 split is your provisional template. Raw marks and percentage weights are separately editable. Confirm lab, internal and end-semester rules with faculty.'}</p></div><div class="stats-grid three"><div class="stat-card"><span>SECURED WEIGHTED MARKS</span><strong>${s.valid?s.secured.toFixed(1):'—'}<small>/ 100</small></strong><p>${s.done}% assessment weight entered; blanks are pending</p></div><div class="stat-card"><span>ASSESSMENT WEIGHTS</span><strong>${s.weight}<small>/ 100%</small></strong><p>${s.valid?'Weights balanced':'Fix weights: they must total exactly 100%'}</p></div><div class="stat-card"><span>YOUR PERSONAL MARKS TARGET</span><strong>${c.targetMarks}<small>/ 100</small></strong><p>${!s.valid?'Configure a valid assessment structure first':s.complete?(s.secured>=c.targetMarks?'Target reached':'Below your personal target'):s.required>100?'Target is not reachable with remaining marks':`Need ${s.required.toFixed(1)}% average on remaining assessments`}</p></div></div><section class="panel table-panel"><div class="section-heading"><div><h2>Assessment ledger</h2><p>Blank marks mean not assessed yet. Zero is a real score.</p></div>${button(`${icon('plus',16)} Add component`,'add-assessment','',`data-id="${c.id}"`)}</div><div class="table-scroll"><table><thead><tr><th>COMPONENT</th><th>MARKS OBTAINED</th><th>OUT OF</th><th>WEIGHT</th><th>DUE DATE</th><th></th></tr></thead><tbody>${c.assessments.map(a=>`<tr><td><b>${esc(a.name)}</b></td><td><input type="number" min="0" max="${a.max}" step="any" value="${a.score}" placeholder="Pending" class="score-input short" data-id="${a.id}" data-course="${c.id}" aria-label="${esc(a.name)} marks"></td><td>${a.max}</td><td>${a.weight}%</td><td>${esc(a.date||'—')}</td><td>${button(icon('edit',15),'edit-assessment','icon-btn',`data-id="${a.id}" data-course="${c.id}" aria-label="Edit assessment"`)}${button(icon('close',15),'delete-assessment','icon-btn',`data-id="${a.id}" data-course="${c.id}" aria-label="Delete assessment"`)}</td></tr>`).join('')}</tbody></table></div>${!c.assessments.length?empty('Not everything is an exam.','Add projects, participation, practicals or any assessment your faculty uses.'):''}</section><div class="two-col equal"><section class="panel padded"><h2>Marks → grade estimator</h2><p>${Object.keys(c.thresholds).length?'Custom cutoffs entered for this course. Estimates do not set your recorded grade.':'No cutoffs configured. Regular courses use relative grading in the reference regulations. A fixed marks-to-letter conversion would be misleading.'}</p>${estimated?`<div class="formula">Estimated grade: ${esc(estimated)} · not an official result</div>`:''}${button('Configure targets & cutoffs','course-rules','',`data-id="${c.id}"`)}<p class="fine-print">Estimates appear only when all weighted assessments are entered, weights total 100%, and cutoffs exist. Passing may require separate end-semester and other conditions.</p></section><section class="panel padded"><h2>Known pass checks</h2><p>Total minimum: <b>${c.minTotal===''?'Not provided':c.minTotal+'/100'}</b><br>End-semester minimum: <b>${c.minEnd===''?'Not provided':c.minEnd+'% of raw exam marks'}</b></p>${passChecks(c,s)}<p class="fine-print">Meeting these checks alone does not certify a pass. Confirm lab minimums, attendance, participation and course-specific requirements.</p></section></div>`;}
function passChecks(c,s){const end=c.assessments.find(a=>/end.semester/i.test(a.name));return `<p>${c.minTotal!==''&&s.complete&&s.valid?`Total minimum ${s.secured>=Number(c.minTotal)?'met':'not met'}. `:''}${c.minEnd!==''&&end&&end.score!==''?`End-semester minimum ${Number(end.score)/end.max*100>=Number(c.minEnd)?'met':'not met'}.`:''}</p>`;}
function planner(){const current=gpa(data.courses,data.settings.gradePoints),taskDone=data.tasks.filter(t=>t.done).length;return heading('Give ambition a direction.','Work backwards from the student you want to become.')+`<div class="two-col equal"><section class="panel padded"><span class="eyebrow">CGPA TARGET PLANNER</span><h2 class="large-heading">What does your goal take?</h2><p>Uses recorded, GPA-included credits across all semesters. Future credits must be GPA-bearing and must not already be included.</p><div class="form-grid"><label>Target CGPA<input id="plan-target" type="number" min="0" max="10" step="0.01" value="${data.settings.target}"></label><label>Future GPA credits<input id="plan-future" type="number" min="0.01" max="1000" step="0.01" value="${Math.max(1,semCourses().filter(c=>c.include&&!c.grade).reduce((s,c)=>s+c.credits,0)||24)}"></label></div><div id="plan-result"></div><p class="fine-print">Current basis: ${current.credits} entered GPA credits · ${fmt(current.value)} CGPA. Unentered grades are not assumed to be zero. This planner does not infer future GPA credits from the 180-credit degree target.</p>${button('Try course-by-course grades →','goto-scenario','text-btn')}</section><section class="panel padded goal-panel"><span class="eyebrow">YOUR PERSONAL NORTH STAR</span><div class="goal-ring"><strong>${fmt(data.settings.target)}</strong><span>TARGET CGPA</span></div><h2>Progress over perfection.</h2><p>Your target is a planning choice, not a promise of an official classification. For an A+ reference grade, the grade point is 9.5; O is 10.</p>${button('Change my target','goto-settings','')}</section></div><section class="panel padded"><div class="section-heading"><div><h2>Small wins, meaningful progress</h2><p>${taskDone} of ${data.tasks.length} tasks completed · all semesters</p></div>${button(`${icon('plus',17)} Add task`,'add-task')}</div>${data.tasks.length?data.tasks.map(taskRow).join(''):empty('A goal needs a next step.','Add a concrete action and a due date.')}</section>`;}
function createNote(projectId=''){const now=new Date().toISOString();const n={id:uid(),title:'',body:'',category:projectId?'Project':'Personal',course:'',projectId,pinned:false,updated:now};data.notes.unshift(n);activeNote=n.id;noteSearch='';save();go('notes');setTimeout(()=>$('#note-title')?.focus(),0);}
function notesPage(){
 const matches=data.notes.filter(n=>(n.title+' '+n.body+' '+n.category).toLowerCase().includes(noteSearch.toLowerCase())).sort((a,b)=>Number(b.pinned)-Number(a.pinned)||b.updated.localeCompare(a.updated));
 let n=matches.find(n=>n.id===activeNote)||matches[0];if(n)activeNote=n.id;
 return heading('A little space to think.','Lecture notes, project thoughts and everything worth remembering.',button(`${icon('plus',16)} New note`,'add-note','primary'))+`<section class="notebook panel"><aside class="note-list"><div class="note-search-wrap"><input id="note-search" placeholder="Search your notes…" aria-label="Search notes" value="${esc(noteSearch)}"><small>${matches.length} notes · private to this browser</small></div>${matches.map(x=>`<button class="note-list-item ${n?.id===x.id?'active':''}" data-action="select-note" data-id="${x.id}"><small>${x.pinned?'PINNED · ':''}${esc(x.category.toUpperCase())}</small><b data-note-label="${x.id}">${esc(x.title||'Untitled note')}</b><p data-note-excerpt="${x.id}">${esc(x.body.slice(0,95)||'Your next thought starts here.')}</p><span>${new Date(x.updated).toLocaleDateString('en-IN',{day:'numeric',month:'short'})}</span></button>`).join('')||'<div class="note-list-empty">No matching notes yet.</div>'}</aside><div class="note-editor">${n?`<div class="note-editor-top"><span class="eyebrow">YOUR PRIVATE NOTEBOOK</span><div>${button(n.pinned?'Unpin':'Pin','pin-note','text-btn',`data-id="${n.id}"`)}${button(icon('download',16),'export-note','icon-btn',`data-id="${n.id}" aria-label="Download note"`)}${button(icon('close',16),'delete-note','icon-btn',`data-id="${n.id}" aria-label="Delete note"`)}</div></div><input id="note-title" data-id="${n.id}" value="${esc(n.title)}" placeholder="Untitled note" maxlength="160" aria-label="Note title"><div class="note-links"><label>Category<select id="note-category">${['Personal','Lecture','Project','Reference'].map(x=>`<option ${x===n.category?'selected':''}>${x}</option>`).join('')}</select></label><label>Course<select id="note-course"><option value="">No course</option>${data.courses.map(c=>`<option value="${c.id}" ${c.id===n.course?'selected':''}>${esc(c.code)}</option>`).join('')}</select></label><label>Project<select id="note-project"><option value="">No project</option>${data.projects.map(p=>`<option value="${p.id}" ${p.id===n.projectId?'selected':''}>${esc(p.title)}</option>`).join('')}</select></label></div><textarea id="note-body" placeholder="Let the ideas out.\n\nCapture a lecture, work through a problem, or write down your next project idea…" maxlength="100000" aria-label="Note content">${esc(n.body)}</textarea><div class="note-editor-bottom"><span id="note-save-status" role="status">Saved in this browser</span><span id="note-word-count">${n.body.trim()?n.body.trim().split(/\s+/).length:0} words</span></div>`:empty(noteSearch?'No notes match your search.':'A blank page. A fresh possibility.','Notes save automatically in this browser. They are never included in your public portfolio.',button('Write a note','add-note','primary'))}</div></section><p class="fine-print">Your notebook is part of your full workspace backup. Notes are not cloud-synced, password-protected or shared with the team website.</p>`;
}
function bindPersonalTools(){
 $('#note-search')?.addEventListener('input',e=>{const pos=e.target.selectionStart;noteSearch=e.target.value;render();$('#note-search').focus();$('#note-search').setSelectionRange(pos,pos);});
 if($('#note-title')){
  const saveNote=()=>{const n=data.notes.find(n=>n.id===$('#note-title').dataset.id);if(!n)return;n.title=$('#note-title').value;n.body=$('#note-body').value;n.category=$('#note-category').value;n.course=$('#note-course').value;n.projectId=$('#note-project').value;n.updated=new Date().toISOString();save();$('#note-save-status').textContent=storageOK?'Saved in this browser':'Not saved — export a backup before leaving';$('#note-word-count').textContent=(n.body.trim()?n.body.trim().split(/\s+/).length:0)+' words';const label=document.querySelector(`[data-note-label="${n.id}"]`),excerpt=document.querySelector(`[data-note-excerpt="${n.id}"]`);if(label)label.textContent=n.title||'Untitled note';if(excerpt)excerpt.textContent=n.body.slice(0,95)||'Your next thought starts here.';};
  for(const id of ['note-title','note-body'])$('#'+id).addEventListener('input',saveNote);
  for(const id of ['note-category','note-course','note-project'])$('#'+id).addEventListener('change',saveNote);
 }
 $('#project-filter')?.addEventListener('change',e=>{projectFilter=e.target.value;render();});
 document.querySelectorAll('.project-status-input').forEach(el=>el.addEventListener('change',()=>{data.projects.find(p=>p.id===el.dataset.id).status=el.value;save();render();}));
}
function projectDashboard(){const items=data.projects.filter(p=>projectFilter==='All'||p.status===projectFilter),milestones=data.projects.flatMap(p=>p.milestones);return heading('From an idea to something real.','Your current projects, the next small steps, and the people you build with.',button(`${icon('plus',16)} Add project`,'add-project','primary'))+`<div class="stats-grid three"><div class="stat-card"><span>PROJECTS IN YOUR SPACE</span><strong>${data.projects.length}</strong><p>Personal work and 404 Error Found projects</p></div><div class="stat-card"><span>IN PROGRESS</span><strong>${data.projects.filter(p=>p.status==='In progress').length}</strong><p>${data.projects.filter(p=>p.status==='Not set').length} with status still to add</p></div><div class="stat-card"><span>MILESTONES COMPLETED</span><strong>${milestones.filter(m=>m.done).length}<small>/ ${milestones.length}</small></strong><p>Only the milestones you have recorded</p></div></div><div class="toolbar"><div class="chips">${tag('404 Error Found')}${tag('Your personal project dashboard','neutral')}</div><select id="project-filter" aria-label="Filter project status">${['All',...PROJECT_STATUSES].map(s=>`<option ${projectFilter===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="project-dashboard-grid">${items.map(p=>`<article class="panel project-dashboard-card"><div class="card-top"><span class="course-letter">${esc(p.title.slice(0,1))}</span>${tag(p.public?'Public portfolio':'Private draft','neutral')}${button(icon('edit',16),'edit-project','icon-btn',`data-id="${p.id}" aria-label="Edit ${esc(p.title)}"`)}</div><span class="eyebrow project-context">${esc(p.context||'YOUR PROJECT')}</span><h2>${esc(p.title)}</h2><p>${esc(p.description||'Add a short description of what you’re building.')}</p><label>Workflow<select class="project-status-input" data-id="${p.id}">${PROJECT_STATUSES.map(s=>`<option ${s===p.status?'selected':''}>${s}</option>`).join('')}</select></label><div class="project-next"><small>NEXT STEP · PRIVATE</small><p>${esc(p.nextStep||'No next step added yet. Make it a small, concrete action.')}</p></div><div class="milestone-heading"><h3>Milestones</h3>${button(icon('plus',16),'add-milestone','icon-btn',`data-id="${p.id}" aria-label="Add milestone to ${esc(p.title)}"`)}</div>${p.milestones.length?p.milestones.map(m=>`<div class="task-row"><button class="task-check ${m.done?'done':''}" data-action="toggle-milestone" data-id="${m.id}" data-project="${p.id}" aria-label="${m.done?'Reopen':'Complete'} ${esc(m.title)}">${m.done?icon('check',13):''}</button><div><b class="${m.done?'struck':''}">${esc(m.title)}</b></div>${button(icon('close',13),'delete-milestone','icon-btn',`data-id="${m.id}" data-project="${p.id}" aria-label="Delete milestone"`)}</div>`).join(''):'<p class="fine-print">A clear next step is a great place to start.</p>'}<div class="project-dashboard-actions">${safeUrl(p.url)?`<a class="btn" href="${esc(safeUrl(p.url))}" target="_blank" rel="noopener">Open project ↗</a>`:''}${button('Add a project note','project-note','text-btn',`data-id="${p.id}"`)}</div></article>`).join('')}</div>${!items.length?empty('No projects in this view.','Try another status or add a new project.'):''}<div class="notice"><p>CivicEye, AgriPulse and MetrikAI are seeded from the details you shared. Their technical details, milestones and current status are left for you to add. Project notes and next steps remain private and are excluded from portfolio exports.</p></div>`;}
function timetable(){return heading('A rhythm for your week.','Your uploaded timetable, preserved without guessing lab groups.')+`<section class="panel padded"><div class="section-heading"><div><h2>Section G · AI & DS</h2><p>Semester 1 · Classroom D205 · Effective 27 July 2026</p></div><a class="btn" href="/timetable.png" target="_blank" rel="noopener">Open full image ↗</a></div><div class="timetable-image"><img src="/timetable.png" alt="Amrita School of Artificial Intelligence Bengaluru, first year 2026–27 odd semester, Section G AI and DS timetable with courses and credits"></div><div class="notice"><p>Monday and Friday labs differ for G1 and G2. Confirm your group before planning. This source is for semester 1 only; attendance is logged independently. You can replace <code>public/timetable.png</code> when the schedule changes.</p></div></section><div class="two-col equal"><section class="panel padded"><h2>Your academic contacts</h2><p><b>Faculty advisors</b><br>Dr. Saurabh Sharma · Mr. Niranjan</p><p><b>Classroom</b><br>D205</p></section><section class="panel padded"><h2>Course slots</h2>${data.courses.filter(c=>c.semester===1).map(c=>`<div class="breakdown"><b>${esc(c.slot)}</b><span>${esc(c.name)}</span></div>`).join('')}</section></div>`;}
function ideas(){return heading('Good ideas need a home.','Course projects, little experiments, questions worth following. Plant them here.',button(`${icon('plus',16)} Plant an idea`,'add-idea','primary'))+`<div class="idea-columns">${['Seed','Growing','Ready'].map((status,i)=>`<section class="idea-column"><div class="idea-col-title"><h2><i class="stage stage-${i}"></i>${status}</h2><span>${data.ideas.filter(x=>x.status===status).length}</span></div>${data.ideas.filter(x=>x.status===status).map(x=>`<article class="panel idea-card">${tag(esc(data.courses.find(c=>c.id===x.course)?.code||'Personal'),'neutral')}<h3>${esc(x.title)}</h3><p class="preserve">${esc(x.body)}</p><div class="idea-bottom"><select class="idea-status" data-id="${x.id}" aria-label="Idea stage">${['Seed','Growing','Ready'].map(s=>`<option ${s===x.status?'selected':''}>${s}</option>`).join('')}</select>${button(icon('edit',15),'edit-idea','icon-btn',`data-id="${x.id}" aria-label="Edit idea"`)}</div></article>`).join('')||`<div class="idea-empty">${icon(i===0?'bulb':i===1?'leaf':'check',25)}<p>${['Every project starts with a spark.','Give a seed some attention.','Make something you can share.'][i]}</p></div>`}</section>`).join('')}</div><section class="panel padded roadmap"><div><span class="eyebrow">A WORKSPACE THAT GROWS WITH YOU</span><h2>What should we build next?</h2><p>Keep a wishlist for the next version. Your personal AI is a future feature—not connected and not reading your data.</p>${button('Suggest a feature','add-feature')}</div><div>${tag('Personal AI · planned','neutral')}${data.features.map(f=>`<div class="breakdown"><span>${esc(f.title)}</span>${button(icon('close',14),'delete-feature','icon-btn',`data-id="${f.id}" aria-label="Delete feature idea"`)}</div>`).join('')}</div></section>`;}
function safeUrl(s){try{const u=new URL(s);return ['https:','http:'].includes(u.protocol)?u.href:'';}catch{return '';}}
function portfolio(){const p=data.profile;return heading('More than a grade sheet.','Your story, your skills, and the work you’re proud of.',button('Edit profile','edit-profile')+button(`${icon('download',16)} Export portfolio`,'export-portfolio','primary'))+`<section class="panel portfolio-hero"><div><span class="eyebrow">B.TECH · AI & DATA SCIENCE · 2026–2030 (EXPECTED)</span><h2>${esc(p.name||'Your name goes here.')}</h2><h3>${esc(p.headline)}</h3><p class="preserve">${esc(p.bio||'Introduce the person behind the projects. Add a short bio, your interests, and what you’re learning next.')}</p><div class="chips">${[p.github,p.linkedin].filter(safeUrl).map((u,i)=>`<a class="btn" href="${esc(safeUrl(u))}" target="_blank" rel="noopener">${u===p.github?'GitHub':'LinkedIn'} ↗</a>`).join('')}${p.email?`<span class="tag neutral">${esc(p.email)}</span>`:''}</div></div><div class="portfolio-monogram">${esc(p.name?p.name.split(' ').slice(0,2).map(x=>x[0]).join(''):'YOU')}<span>A WORK IN PROGRESS.<br>IN THE BEST WAY.</span></div></section><div class="two-col"><section class="panel padded"><div class="section-heading"><div><h2>Selected projects</h2><p>Only projects you choose are included in your public export.</p></div>${button(`${icon('plus',16)} Add project`,'add-project')}</div>${data.projects.length?data.projects.map(p=>`<article class="project-item"><span class="soft-icon">${icon('folder')}</span><div><h3>${esc(p.title)}</h3><p class="preserve">${esc(p.description)}</p><small>${esc(p.tech)} · ${p.public?'Included in export':'Private draft'}</small>${safeUrl(p.url)?`<p><a href="${esc(safeUrl(p.url))}" target="_blank" rel="noopener">Explore project ↗</a></p>`:''}</div>${button(icon('edit',16),'edit-project','icon-btn',`data-id="${p.id}" aria-label="Edit project"`)}</article>`).join(''):empty('Your first project belongs here.','Build something small. Document what you learned. Share it proudly.')}</section><section class="panel padded"><span class="eyebrow">THE ONE-PAGE STORY</span><h2>Résumé studio</h2><p>Your profile and public projects become a clean, printable résumé. Private grades, attendance and notes are never included.</p><h3>Skills</h3><div class="chips">${p.skills?p.skills.split(',').map(s=>tag(esc(s.trim()),'neutral')).join(''):'<p class="subtle">Add skills in your profile.</p>'}</div><h3>Experience & achievements</h3><p class="preserve">${esc(p.experience||'Add experiences as you build them. Nothing is invented for you.')}</p>${button(`${icon('download',16)} Download résumé HTML`,'export-resume','')}<p class="fine-print">Open the downloaded file and use Print → Save as PDF.</p></section></div><div class="notice">${icon('person')}<p>This is a local portfolio editor, not a published website or account system. Exports include only your profile and projects marked public. Review contact details before sharing. Academic data remains in your browser. <button data-action="goto-settings">Configure website & hosting →</button></p></div>`;}
function hostingSettings(){const site=data.site;return `<section class="panel padded hosting-panel"><div class="section-heading"><div><span class="eyebrow">ONE ARCHISPACE. ALL YOUR TOOLS.</span><h2>Website & hosting</h2><p>The website homepage is always your complete workspace: college calculators, notes, projects and portfolio.</p></div>${tag('Workspace-first')}</div><div class="two-col equal"><form id="site-form">${field('Public website title','title',site.title,'text','required maxlength="120"')}${area('Search & sharing description','description',site.description,'rows="3" required maxlength="300"')}${field('Public site origin (optional)','url',site.url,'text','placeholder="https://architspace.vercel.app" maxlength="250"')}<p class="fine-print">This edits export metadata. It does not purchase a domain, edit DNS or deploy the site.</p><button class="btn primary" type="submit">Save website preferences</button></form><div class="hosting-path"><span class="eyebrow">YOUR WEBSITE, NOT JUST A PORTFOLIO</span><h3>College first. Everything connected.</h3><p>Your calculators, notes and project dashboard live on the homepage. A public-only portfolio is also included at <code>/portfolio/</code>, with a printable résumé at <code>/resume.html</code>.</p><p>Old portfolio-only deployment-mode variables are ignored. The normal deployment build always includes the full workspace.</p><div class="button-row">${button('Download public config','export-public-config')}${button('Export portfolio HTML','export-portfolio','text-btn')}</div><p class="fine-print">Browser edits are local, not automatically uploaded. A public config export contains only your profile and public projects. Private notes, milestones, grades and attendance are excluded.</p></div></div><details class="hosting-details"><summary>Privacy, changing domains & future AI</summary><p>The workspace is browser-local, not an authenticated cloud account. Full backups include private notes and academic records; never commit them to GitHub. Moving to a different domain requires exporting and importing a backup.</p><p>Your future personal AI is not connected. API credentials belong on a secure backend, not in this browser app.</p></details></section>`;}
function settings(){const s=data.settings;return heading('Make this space yours.','Editable by design. Honest about what’s confirmed and what isn’t.')+hostingSettings()+`<div class="two-col equal"><section class="panel padded"><h2>Workspace preferences</h2><form id="settings-form"><div class="form-grid"><label>Attendance minimum (%)<input name="minimum" type="number" min="1" max="100" step="0.1" required value="${s.minimum}"></label><label>Degree credit target*<input name="degreeCredits" type="number" min="1" max="1000" required value="${s.degreeCredits}"></label><label>Target CGPA<input name="target" type="number" min="0" max="10" step="0.01" required value="${s.target}"></label><label>Accent colour<input name="accent" type="color" value="${s.accent}"></label></div><div class="palette">${['#1b4332','#2d6a4f','#f1faee','#b31237','#e63946'].map(h=>`<span style="--swatch:${h}"><i></i>${h}</span>`).join('')}</div><p class="fine-print">*180 is your provisional degree-wide target. It is not a per-course requirement and does not automatically represent 180 GPA-bearing credits. Graduation also depends on required courses and other official conditions.</p><label class="checkbox"><input type="checkbox" name="confirmed" ${s.confirmed?'checked':''}> I have confirmed these grading rules with my faculty for my batch.</label><button class="btn primary" type="submit">Save preferences</button></form></section><section class="panel padded"><h2>Grade-point reference</h2><p>Amrita School of Computing, May 2024, R.16.2. Fixed points, not point ranges. Applicability to School of AI 2026: <b>${s.confirmed?'marked confirmed by you':'not yet confirmed'}</b>.</p><form id="points-form"><div class="grade-scale">${Object.entries(s.gradePoints).map(([g,p])=>`<label>${g}<input name="${g}" type="number" min="0" max="10" step="0.01" required value="${p}" aria-label="${g} grade points"></label>`).join('')}</div><button class="btn" type="submit">Save grade points</button> ${button('Restore reference','reset-points','text-btn')}</form><p class="fine-print">W (withheld) is unresolved, not assigned zero. I uses the reference’s zero-point value. FIH pass/fail GPA inclusion and pass points can be changed in the course editor.</p></section></div><section class="panel padded"><h2>Sources & assumptions</h2><div class="source-grid"><div><h3>Provided by you</h3><ul><li>AI & DS · Semester 1 · Admission 2026.</li><li>2026–27 Section G timetable: 9 courses, 26 credits. Timetable is preferred over older curriculum if a course code differs.</li><li>75% minimum attendance per course.</li><li>FIH pass/fail; FIH and Mastery Over Mind use practical/participation-based assessments.</li><li>10 + 10 + 50 + 30 assessment template, configurable per course.</li><li>180-credit degree target, awaiting official curriculum confirmation.</li></ul></div><div><h3>Official reference, batch confirmation pending</h3><ul><li>R.16.1: regular courses use relative grading.</li><li>R.20–21: SGPA / CGPA are credit-weighted, include failed courses, and round to two decimals.</li><li>The fixed marks chart in R.16.5 is for online NPTEL / SWAYAM courses, not a universal campus grading chart. It is not applied here.</li><li>FIH’s GPA exclusion is provisional. No repeat-course substitution or pass cutoffs are automatically assumed.</li></ul><div class="source-links">${sourceLinks}</div></div></div><p class="fine-print">Reference documents consulted 28 September 2026. A 2023-onwards School of Computing document is not proof of the exact rules for School of Artificial Intelligence, Bengaluru, 2026. Confirm with your advisor. Expected graduation in 2030 assumes a normal four-year programme.</p></section><section class="panel padded"><div class="section-heading"><div><h2>Your data stays yours.</h2><p>No login, server database, analytics or AI connection. Saved only in this browser on this site origin.</p></div>${tag(storageOK?'Local saving active':'Storage unavailable',storageOK?'':'danger')}</div><p>Clearing browser storage, private browsing, a new device or a different preview URL can lose your saved data. Export backups regularly. This workspace is not password-protected; do not use it on a shared browser for sensitive information.</p><div class="button-row">${button(`${icon('download',17)} Export full backup`,'backup','primary')}${button('Import backup','import')}${button('Reset workspace','reset','danger-text')}<input type="file" id="import-file" accept="application/json,.json" hidden></div><p class="fine-print">Full backups contain private academic data. Portfolio and résumé exports do not. Import replaces this browser’s workspace after confirmation.</p></section>`;}
function bindInputs(){
 bindPersonalTools();
 $('#site-form')?.addEventListener('submit',e=>{e.preventDefault();try{const f=new FormData(e.target);const url=normalizeSiteUrl(f.get('url'));data.site={title:f.get('title').trim(),description:f.get('description').trim(),url};save();render();toast('Website preferences saved. Nothing has been published or connected.');}catch(err){toast(err.message);}});

 $('#semester')?.addEventListener('change',e=>{semester=Number(e.target.value);render();});
 $('#course-search')?.addEventListener('input',e=>{const pos=e.target.selectionStart;search=e.target.value;render();$('#course-search').focus();$('#course-search').setSelectionRange(pos,pos);});
 document.querySelectorAll('.grade-input').forEach(el=>el.addEventListener('change',e=>{const c=data.courses.find(x=>x.id===el.dataset.id);if(scenario)c.plan=el.value;else{if(c.grade!==el.value&&c.grade)c.history.push({grade:c.grade,date:new Date().toISOString()});c.grade=el.value;}save();render();}));
 $('#assessment-course')?.addEventListener('change',e=>{selected=e.target.value;render();});
 document.querySelectorAll('.score-input').forEach(el=>el.addEventListener('change',()=>{const c=data.courses.find(x=>x.id===el.dataset.course),a=c.assessments.find(x=>x.id===el.dataset.id);if(el.value!==''&&(!el.checkValidity()||!Number.isFinite(Number(el.value)))){toast('Marks must be between 0 and the maximum.');el.value=a.score;return;}a.score=el.value===''?'':Number(el.value);save();render();}));
 document.querySelectorAll('.idea-status').forEach(el=>el.addEventListener('change',()=>{data.ideas.find(x=>x.id===el.dataset.id).status=el.value;save();render();}));
 if($('#plan-result')){const update=()=>{const t=Number($('#plan-target').value),f=Number($('#plan-future').value),cur=gpa(data.courses,data.settings.gradePoints);if(!$('#plan-target').value||!$('#plan-future').value||!$('#plan-target').checkValidity()||!$('#plan-future').checkValidity()){$('#plan-result').innerHTML='<p class="error">Enter a target from 0–10 and positive future GPA credits.</p>';return;}const r=requiredGpa(cur,t,f);$('#plan-result').innerHTML=`<div class="planner-result"><span>REQUIRED AVERAGE ON FUTURE CREDITS</span><strong>${r>10?'Beyond 10.00':fmt(Math.max(0,r))}</strong><p>${r>10?'This goal is not reachable over those credits on a 10-point scale. Try more future credits or a lower target.':r<=0?'Your entered quality points already cover this mathematical target. You still need to pass required courses.':`Aim for an average of ${fmt(r)} across the next ${f} GPA credits.`}</p></div>`;};$('#plan-target').addEventListener('input',update);$('#plan-future').addEventListener('input',update);update();}
 $('#settings-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);for(const k of ['minimum','degreeCredits','target'])data.settings[k]=Number(f.get(k));data.settings.accent=f.get('accent');data.settings.confirmed=f.has('confirmed');save();render();toast('Workspace preferences saved.');});
 $('#points-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);Object.keys(data.settings.gradePoints).forEach(k=>data.settings.gradePoints[k]=Number(f.get(k)));save();render();toast('Grade points updated. All GPA calculations refreshed.');});
 $('#import-file')?.addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5e6)throw Error('Backup is too large (maximum 5 MB).');const next=migratePersonalization(validate(JSON.parse(await file.text())));if(confirm('Replace this workspace with the imported backup? Export your current data first if you need it.')){data=next;save();render();toast('Backup restored.');}}catch(err){toast('Import rejected: '+err.message);} });
}
function field(label,name,value='',type='text',extra=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function area(label,name,value='',extra=''){return `<label>${label}<textarea name="${name}" ${extra}>${esc(value)}</textarea></label>`;}
function check(label,name,value){return `<label class="checkbox"><input type="checkbox" name="${name}" ${value?'checked':''}>${label}</label>`;}
function openDialog(title,body,onSubmit,extra=''){const d=$('#dialog');d.innerHTML=`<div class="modal-heading"><h2>${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div><form id="modal-form">${body}<div class="modal-footer">${extra}<button class="btn" type="button" data-action="close-modal">Cancel</button><button class="btn primary" type="submit">Save changes</button></div></form>`;d.showModal();$('#modal-form').addEventListener('submit',e=>{e.preventDefault();try{onSubmit(new FormData(e.target));save();d.close();render();toast('Saved to your workspace.');}catch(err){toast(err.message);}});}
function editCourse(c){const isNew=!c;c=c||{id:uid(),slot:'',code:'',name:'',credits:3,semester,ltp:'',faculty:'',pf:false,include:true,passPoints:5,grade:'',plan:'',attended:0,held:0,assessments:[],thresholds:{},targetMarks:85,minTotal:'',minEnd:'',notes:'',history:[]};openDialog(isNew?'Add a course':'Edit course',`<div class="form-grid">${field('Course title','name',c.name,'text','required maxlength="160"')}${field('Course code','code',c.code,'text','required maxlength="30"')}${field('Credits (CR)','credits',c.credits,'number','required min="0" max="50" step="0.5"')}${field('Semester','semester',c.semester,'number','required min="1" max="16" step="1"')}${field('Slot letter','slot',c.slot)}${field('L–T–P (reference only)','ltp',c.ltp)}${field('Faculty','faculty',c.faculty)}${field('Pass/fail pass points (only if included in GPA)','passPoints',c.passPoints,'number','required min="0" max="10" step="0.01"')}</div>${check('Pass / fail course','pf',c.pf)}${check('Include in SGPA / CGPA','include',c.include)}<p class="fine-print">Pass/fail inclusion must match your official rules. Changing grading type clears incompatible recorded / planned grades. New courses start without assumed assessment weights.</p>`,f=>{const pf=f.has('pf');if(pf!==c.pf){if(c.grade)c.history.push({grade:c.grade,date:new Date().toISOString()});c.grade='';c.plan='';}for(const k of ['name','code','slot','ltp','faculty'])c[k]=f.get(k).trim();for(const k of ['credits','semester','passPoints'])c[k]=Number(f.get(k));c.pf=pf;c.include=f.has('include');if(isNew)data.courses.push(c);},!isNew?button('Delete course','delete-course','danger-text',`data-id="${c.id}" type="button"`):'');}
function openCourse(c){const d=$('#dialog');const a=attendance(c.attended,c.held,data.settings.minimum);d.innerHTML=`<div class="modal-heading"><div><small>${esc(c.code)} · ${c.credits} credits</small><h2>${esc(c.name)}</h2></div><button class="icon-btn" data-action="close-modal" aria-label="Close">${icon('close')}</button></div><div class="chips">${tag(c.pf?'Pass / fail':'Letter graded')}${tag(c.include?'Included in GPA':'Excluded from GPA','neutral')}</div><p>${esc(c.faculty)} · L–T–P ${esc(c.ltp)}</p><div class="button-row">${button('Edit course','edit-course','',`data-id="${c.id}"`)}${button('Assessments','course-assessments','',`data-id="${c.id}"`)}${button('Marks rules','course-rules','',`data-id="${c.id}"`)}</div><div class="form-grid course-detail"><div><small>Recorded grade</small><h2>${esc(c.grade||'Not entered')}</h2></div><div><small>Attendance</small><h2>${percent(a.pct)}</h2></div></div><form id="notes-form">${area('Private course notes','notes',c.notes,'rows="5" placeholder="Ideas, resources, practical requirements…"')}<div class="modal-footer">${button('Update grade','course-grade','',`data-id="${c.id}" type="button"`)}<button class="btn primary" type="submit">Save notes</button></div></form><h3>Previous recorded grades</h3>${c.history.length?c.history.slice().reverse().map(h=>`<p class="fine-print">${esc(h.grade)} · changed ${new Date(h.date).toLocaleDateString('en-IN')}</p>`).join(''):'<p class="fine-print">No changes recorded. History is informational; only the current grade is used in GPA.</p>'}`;d.showModal();$('#notes-form').addEventListener('submit',e=>{e.preventDefault();c.notes=new FormData(e.target).get('notes');save();d.close();toast('Course notes saved.');});}
function courseRules(c){openDialog('Targets & course-specific rules',`<p>Keep unknown cutoffs blank. Only enter faculty-provided cutoffs or your own explicitly provisional estimates. These do not change recorded grades.</p><div class="form-grid">${field('Personal total-marks target /100','targetMarks',c.targetMarks,'number','required min="0" max="100" step="0.1"')}${field('Minimum total /100 (optional)','minTotal',c.minTotal,'number','min="0" max="100" step="0.1"')}${field('Minimum end-semester % (optional)','minEnd',c.minEnd,'number','min="0" max="100" step="0.1"')}</div><h3>Custom lower-bound cutoffs /100</h3><p class="fine-print">Configure a complete descending scale for estimates. F = 0, or FAIL = 0 for pass/fail. With no cutoffs, grade conversion stays disabled.</p><div class="grade-scale">${(c.pf?['PASS','FAIL']:['O','A+','A','B+','B','C','P','F']).map(g=>field(g,'cut_'+g,c.thresholds[g]??'','number','min="0" max="100" step="0.01"')).join('')}</div>`,f=>{const thresholds={},scale=c.pf?['PASS','FAIL']:['O','A+','A','B+','B','C','P','F'];for(const g of scale){const v=f.get('cut_'+g);if(v!=='')thresholds[g]=Number(v);}const arr=Object.values(thresholds);if(arr.length&&(arr.length!==scale.length||arr.at(-1)!==0||arr.some((v,i)=>i&&v>=arr[i-1])))throw Error('Enter all cutoffs in strictly descending order, ending at 0, or leave them all blank.');c.thresholds=thresholds;c.targetMarks=Number(f.get('targetMarks'));c.minTotal=f.get('minTotal')===''?'':Number(f.get('minTotal'));c.minEnd=f.get('minEnd')===''?'':Number(f.get('minEnd'));});}
function editAssessment(c,a){const isNew=!a;a=a||{id:uid(),name:'',max:100,weight:0,score:'',date:''};openDialog(isNew?'Add assessment component':'Edit assessment component',`<p>Raw maximum and overall percentage weight can differ. For example, a test out of 50 may carry only 20% weight.</p><div class="form-grid">${field('Component name','name',a.name,'text','required maxlength="100"')}${field('Raw maximum marks','max',a.max,'number','required min="0.01" max="10000" step="any"')}${field('Weight in final total (%)','weight',a.weight,'number','required min="0" max="100" step="any"')}${field('Obtained marks (blank = pending)','score',a.score,'number','min="0" step="any"')}${field('Due date','date',a.date,'date')}</div>`,f=>{const max=Number(f.get('max')),score=f.get('score')===''?'':Number(f.get('score'));if(score!==''&&score>max)throw Error('Obtained marks cannot exceed the raw maximum.');Object.assign(a,{name:f.get('name').trim(),max,score,weight:Number(f.get('weight')),date:f.get('date')});if(isNew)c.assessments.push(a);});}
function courseSelect(value=''){return `<label>Link to a course<select name="course"><option value="">Personal / no course</option>${data.courses.map(c=>`<option value="${c.id}" ${value===c.id?'selected':''}>${esc(c.code)} · ${esc(c.name)}</option>`).join('')}</select></label>`;}
function editIdea(item){const isNew=!item;item=item||{id:uid(),title:'',body:'',course:'',status:'Seed'};openDialog(isNew?'Plant a new idea':'Nurture this idea',field('Give it a name','title',item.title,'text','required maxlength="150"')+area('What are you thinking?','body',item.body,'rows="5" maxlength="10000"')+courseSelect(item.course),f=>{Object.assign(item,{title:f.get('title').trim(),body:f.get('body'),course:f.get('course')});if(isNew)data.ideas.push(item);},!isNew?button('Delete idea','delete-idea','danger-text',`data-id="${item.id}" type="button"`):'');}
function editProfile(){const p=data.profile;openDialog('The person behind the projects',`<div class="form-grid">${field('Your name','name',p.name,'text','maxlength="100"')}${field('Headline','headline',p.headline,'text','maxlength="160"')}${field('Public contact email (optional)','email',p.email,'email')}${field('GitHub URL','github',p.github,'url')}${field('LinkedIn URL','linkedin',p.linkedin,'url')}</div>${area('A short introduction','bio',p.bio,'rows="4"')}${field('Skills, separated by commas','skills',p.skills)}${area('Experience & achievements','experience',p.experience,'rows="5"')}<p class="fine-print">These fields appear in portfolio and résumé exports. Do not add private information you would not share publicly.</p>`,f=>{Object.keys(p).forEach(k=>p[k]=f.get(k)||'');});}
function editProject(p){const isNew=!p;p=p||{id:uid(),title:'',description:'',tech:'',url:'',public:false,status:'Not set',nextStep:'',context:'',milestones:[]};openDialog(isNew?'Add a project':'Edit project',field('Project title','title',p.title,'text','required maxlength="160"')+area('What did you build or learn?','description',p.description,'rows="4"')+field('Project context','context',p.context,'text','placeholder="Personal, hackathon, course project…"')+`<label>Workflow status<select name="status">${PROJECT_STATUSES.map(s=>`<option ${s===p.status?'selected':''}>${s}</option>`).join('')}</select></label>`+field('Tools / technologies','tech',p.tech)+field('Project URL (optional)','url',p.url,'url')+area('Next step (private, excluded from portfolio)','nextStep',p.nextStep,'rows="2"')+check('Include this project in public portfolio and résumé exports','public',p.public),f=>{Object.assign(p,{title:f.get('title'),description:f.get('description'),tech:f.get('tech'),url:f.get('url'),public:f.has('public'),status:f.get('status'),nextStep:f.get('nextStep'),context:f.get('context')});if(isNew)data.projects.push(p);},!isNew?button('Delete project','delete-project','danger-text',`data-id="${p.id}" type="button"`):'');}
function download(name,text,type='application/json'){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function publicExport(resume=false){const html=renderPublicSite(publicSnapshot(data),{resume});download(resume?'archit-renjeev-resume.html':'archit-renjeev-portfolio.html',html,'text/html');toast('Exported profile and public projects only.');}

document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action,id=el.dataset.id,c=data.courses.find(x=>x.id===id);if(action.startsWith('goto-')){if(action==='goto-scenario'){scenario=true;go('grades');}else go(action.slice(5));return;}
 const close=()=>$('#dialog').close();
 switch(action){
 case 'menu':document.querySelector('.sidebar').classList.toggle('mobile-open');break;
 case 'close-modal':close();break;
 case 'add-course':editCourse();break;
 case 'edit-course':close();editCourse(c);break;
 case 'open-course':openCourse(c);break;
 case 'course-rules':close();courseRules(c);break;
 case 'course-assessments':selected=id;semester=c.semester;close();go('assessments');break;
 case 'course-grade':semester=c.semester;scenario=false;close();go('grades');break;
 case 'delete-course':if(confirm('Delete this course and all of its grades, attendance, notes and assessment data?')){data.courses=data.courses.filter(x=>x.id!==id);save();close();render();}break;
 case 'actual-mode':scenario=false;render();break;
 case 'scenario-mode':scenario=true;render();break;
 case 'att-present':c.attended++;c.held++;save();render();toast('Attended class logged. Use Edit to correct counts.');break;
 case 'att-missed':c.held++;save();render();toast('Missed class logged. Use Edit to correct counts.');break;
 case 'edit-attendance':openDialog('Edit attendance counts',`<p>${esc(c.name)}</p><div class="form-grid">${field('Classes attended','attended',c.attended,'number','required min="0" step="1"')}${field('Classes held','held',c.held,'number','required min="0" step="1"')}</div>`,f=>{const a=Number(f.get('attended')),h=Number(f.get('held'));if(attendance(a,h).error)throw Error('Attended must be a whole number between zero and classes held.');c.attended=a;c.held=h;});break;
 case 'add-assessment':editAssessment(c);break;
 case 'edit-assessment':{const cc=data.courses.find(x=>x.id===el.dataset.course);editAssessment(cc,cc.assessments.find(a=>a.id===id));break;}
 case 'delete-assessment':if(confirm('Delete this component and its score?')){const cc=data.courses.find(x=>x.id===el.dataset.course);cc.assessments=cc.assessments.filter(a=>a.id!==id);save();render();}break;
 case 'add-task':openDialog('One small win',field('What will you do?','title','','text','required maxlength="180"')+field('Due date (optional)','date','','date')+courseSelect(),f=>{data.tasks.push({id:uid(),title:f.get('title'),date:f.get('date'),course:f.get('course'),done:false});});break;
 case 'toggle-task':{const t=data.tasks.find(t=>t.id===id);t.done=!t.done;save();render();break;}
 case 'delete-task':if(confirm('Delete this task?')){data.tasks=data.tasks.filter(t=>t.id!==id);save();render();}break;
 case 'add-idea':editIdea();break;
 case 'edit-idea':editIdea(data.ideas.find(x=>x.id===id));break;
 case 'delete-idea':if(confirm('Delete this idea?')){data.ideas=data.ideas.filter(x=>x.id!==id);save();close();render();}break;
 case 'add-feature':openDialog('Your next workspace feature',field('What would make this space better?','title','','text','required maxlength="250"'),f=>{data.features.push({id:uid(),title:f.get('title')});});break;
 case 'delete-feature':data.features=data.features.filter(x=>x.id!==id);save();render();break;
 case 'edit-profile':editProfile();break;
 case 'add-project':editProject();break;
 case 'edit-project':editProject(data.projects.find(x=>x.id===id));break;
 case 'delete-project':if(confirm('Delete this project?')){data.projects=data.projects.filter(x=>x.id!==id);save();close();render();}break;
 case 'export-portfolio':publicExport();break;
 case 'export-resume':publicExport(true);break;
 case 'add-note':createNote();break;
 case 'project-note':createNote(id);break;
 case 'select-note':activeNote=id;render();break;
 case 'pin-note':{const n=data.notes.find(n=>n.id===id);n.pinned=!n.pinned;save();render();break;}
 case 'delete-note':if(confirm('Delete this private note?')){data.notes=data.notes.filter(n=>n.id!==id);activeNote='';save();render();}break;
 case 'export-note':{const n=data.notes.find(n=>n.id===id);download('archispace-note-'+id+'.md','# '+(n.title||'Untitled note')+'\n\n'+n.body,'text/markdown');break;}
 case 'add-milestone':openDialog('A small step for '+esc(c?.name||'your project'),field('Milestone','title','','text','required maxlength="180"'),f=>{data.projects.find(p=>p.id===id).milestones.push({id:uid(),title:f.get('title'),done:false});});break;
 case 'toggle-milestone':{const p=data.projects.find(p=>p.id===el.dataset.project),m=p.milestones.find(m=>m.id===id);m.done=!m.done;save();render();break;}
 case 'delete-milestone':{const p=data.projects.find(p=>p.id===el.dataset.project);p.milestones=p.milestones.filter(m=>m.id!==id);save();render();break;}
 case 'export-public-config':download('public-profile.json',JSON.stringify(publicSnapshot(data),null,2));toast('Public-only snapshot downloaded. Add it to the project root before deploying.');break;
 case 'backup':download('archispace-backup-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(data,null,2));break;
 case 'import':$('#import-file').click();break;
 case 'reset-points':if(confirm('Restore Amrita reference grade points? This recalculates all GPA previews.')){data.settings.gradePoints={...GRADES};data.settings.confirmed=false;save();render();}break;
 case 'reset':if(confirm('Reset ALL grades, attendance, notes, projects and settings? Export a full backup first.')){data=initial();semester=1;save();render();toast('Workspace reset.');}break;
 case 'export-csv':{const safeCell=v=>{let s=String(v??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};const rows=[['Semester','Code','Course','Credits','In GPA','Recorded grade','Grade points','Planned grade'],...data.courses.map(c=>[c.semester,c.code,c.name,c.credits,c.include,c.grade,point(c,c.grade,data.settings.gradePoints)??'',c.plan])];download('archispace-grades.csv',rows.map(r=>r.map(safeCell).join(',')).join('\r\n'),'text/csv');break;}
 }
});
render();
if(!storageOK)toast('Saved data could not be loaded. Export existing storage before resetting if needed.');
